-- Attach the Drive documents to each imported invoice.
-- 97 invoices get their invoice/PO PDF, 29 get payment documents.
-- Files stay in Drive (single source of truth); the app links straight to them.
-- Safe to re-run: it simply re-sets the same links.
-- ============================================================================

alter table public.payment_requests add column if not exists drive_invoice_files jsonb;
alter table public.payment_requests add column if not exists drive_payment_files jsonb;

